#include "longhorn.h"
static void on_explorer_clicked(GtkButton *button, gpointer user_data){(void)button;create_file_explorer(GTK_APPLICATION(user_data),g_get_home_dir());}
void create_desktop(GtkApplication*app){GtkWidget*w=gtk_application_window_new(app);GtkWindow*win=GTK_WINDOW(w);gtk_layer_init_for_window(win);gtk_layer_set_layer(win,GTK_LAYER_SHELL_LAYER_BACKGROUND);gtk_layer_set_anchor(win,GTK_LAYER_SHELL_EDGE_TOP,TRUE);gtk_layer_set_anchor(win,GTK_LAYER_SHELL_EDGE_BOTTOM,TRUE);gtk_layer_set_anchor(win,GTK_LAYER_SHELL_EDGE_LEFT,TRUE);gtk_layer_set_anchor(win,GTK_LAYER_SHELL_EDGE_RIGHT,TRUE);GtkWidget*r=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);gtk_widget_add_css_class(r,"lh-desktop");gtk_widget_add_css_class(r,"lh-wallpaper");gtk_window_set_child(win,r);GtkWidget*t=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,0);gtk_widget_set_vexpand(t,TRUE);gtk_box_append(GTK_BOX(r),t);GtkWidget*i=gtk_box_new(GTK_ORIENTATION_VERTICAL,4);gtk_widget_set_margin_top(i,18);gtk_widget_set_margin_start(i,14);gtk_box_append(GTK_BOX(t),i);GtkWidget*b=gtk_button_new_with_label("♻\nRecycle Bin");gtk_widget_set_size_request(b,100,78);gtk_box_append(GTK_BOX(i),b);GtkWidget*wm=gtk_label_new("LH4051-DE\nWindows Longhorn PDC 2003 · Build 4051");gtk_widget_add_css_class(wm,"lh-watermark");gtk_widget_set_halign(wm,GTK_ALIGN_END);gtk_widget_set_valign(wm,GTK_ALIGN_END);gtk_widget_set_margin_end(wm,12);gtk_widget_set_margin_bottom(wm,48);gtk_box_append(GTK_BOX(t),wm);g_signal_connect(b,"clicked",G_CALLBACK(on_explorer_clicked),app);gtk_window_present(win);}
